css:
[data-bz-section="location-grid"] .bz-block { padding-block: 0 }
[data-bz-section="location-grid"] .bz-block + .bz-block { padding-block-start: 0 }
[data-bz-section="location-grid"] .bz-row + .bz-row { margin-top: 0 }
[data-bz-section="location-grid"] h2 { margin: 0 0 18px }
[data-bz-section="location-grid"] [data-bz-node="lg-body"] p { font-size: 16px; line-height: 1.7; color: var(--body-text); margin: 0 0 40px; max-width: 820px }
[data-bz-section="location-grid"] h3 { font-size: 21px; line-height: 1.6; margin: 0 0 6px }
[data-bz-section="location-grid"] [data-bz-node^="lg-card-h"] .bz-eyebrow { font-size: 10px; line-height: 1.3; letter-spacing: .14em; color: var(--accent); margin-bottom: 12px }
[data-bz-section="location-grid"] [data-bz-node^="lg-card-addr"] p { font-size: 14px; line-height: 1.6; color: var(--muted); margin: 0 0 18px }
[data-bz-section="location-grid"] [data-bz-node^="lg-card-hours"] .bz-text { display: flex; flex-direction: column; gap: 8px; margin-bottom: 18px }
[data-bz-section="location-grid"] [data-bz-node^="lg-card-hours"] p { font-size: 14px; line-height: 1.5; color: var(--body-text); border-top: 1px solid var(--line); padding-top: 8px; margin: 0 }
[data-bz-section="location-grid"] [data-bz-node^="lg-card-perks"] p { font-size: 13px; line-height: 1.55; color: var(--muted); margin: 0 0 18px }
/* The handoff sets the phone 14px under the card's own text, not against the
   card floor: in a row of four, three of them end well above it. */
[data-bz-section="location-grid"] [data-bz-node^="lg-card-cta"] { margin-top: 14px }
[data-bz-section="location-grid"] [data-bz-node^="lg-card-links"] { padding-block-start: 8px }
[data-bz-section="location-grid"] .bz-btns { margin-block: 0; gap: 8px; flex-direction: column; align-items: flex-start }
[data-bz-section="location-grid"] .bz-btn--link { line-height: 1.6 }
[data-bz-section="location-grid"] [data-bz-node^="lg-map"] .bz-map { width: 100%; aspect-ratio: auto; min-height: 440px; margin-bottom: 40px }
@media (max-width: 640px) {
  [data-bz-section="location-grid"] [data-bz-node^="lg-card-h"] .bz-eyebrow { font-size: 12px; }
}
